"""Compute simple text statistics."""


def stats(text):
    words = text.split()
    if not words:
        return {'words': 0, 'longest': '', 'avg_len': 0.0}
    longest = max(words, key=len)
    return {'words': len(words), 'longest': longest, 'avg_len': sum(len(w) for w in words) / len(words)}

from text_stats import stats


def test_regression_whitespace_only():
    assert stats("   ") == {"words": 0, "longest": "", "avg_len": 0.0}
